"use client";

import { useId, useState } from "react";

import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";

import { BlockFrame } from "../parts/block-frame";
import { AppPage } from "./sidebar/app-page";
import { Brand } from "./sidebar/brand";
import { APP_NAV, DOCS_NAV, INBOX_NAV, type Variant } from "./sidebar/data";
import { DocsPage } from "./sidebar/docs-page";
import { InboxPage } from "./sidebar/inbox-page";
import { Shell } from "./sidebar/shell";
import { WorkspaceShell } from "./sidebar/workspace-shell";

const VARIANTS: { value: Variant; label: string; note: string }[] = [
  { value: "app", label: "App rail", note: "The main places of the app, folding to an icon rail." },
  { value: "workspace", label: "Workspace", note: "One clinic's areas under a clinic switcher." },
  { value: "inbox", label: "Inbox", note: "Message folders with unread counts beside a mail page." },
  { value: "docs", label: "Docs", note: "A tree of help articles beside the open article." },
];

/**
 * App and docs sidebars in four layouts behind tabs: an app rail, a clinic
 * workspace, an inbox and a docs tree. Each folds to an icon rail on a spring
 * and opens as a sheet on a phone. The [ key folds or opens the sidebar.
 */
export function Sidebar({ className }: { className?: string }) {
  const titleId = useId();
  const [variant, setVariant] = useState<Variant>("app");
  const note = VARIANTS.find((option) => option.value === variant)?.note;

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <Tabs value={variant} onValueChange={(next) => setVariant(VARIANTS.find((option) => option.value === next)?.value ?? "app")}>
        <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-5 py-4">
          <div className="min-w-0">
            <h2 id={titleId} className="text-base font-semibold">
              Sidebars
            </h2>
            <p className="text-sm text-muted-foreground">{note} Press [ to fold.</p>
          </div>
          <div className="scroll-fade-effect-x scrollbar-none max-w-full overflow-x-auto">
            <TabsList aria-label="Sidebar layout">
              {VARIANTS.map((option) => (
                <TabsTrigger key={option.value} value={option.value}>
                  {option.label}
                </TabsTrigger>
              ))}
            </TabsList>
          </div>
        </header>
        <div className="p-3 @md:p-5">
          <TabsContent value="app">
            <Shell root="Fernhill" sections={APP_NAV} top={(folded) => <Brand folded={folded} name="Fernhill" />} initialActive="harbour" initialExpanded={["clinics"]}>
              {(active, label) => <AppPage id={active} title={label} />}
            </Shell>
          </TabsContent>
          <TabsContent value="workspace">
            <WorkspaceShell />
          </TabsContent>
          <TabsContent value="inbox">
            <Shell root="Messages" sections={INBOX_NAV} top={(folded) => <Brand folded={folded} name="Fernhill mail" />} initialActive="inbox">
              {(active) => <InboxPage key={active} folder={active} />}
            </Shell>
          </TabsContent>
          <TabsContent value="docs">
            <Shell root="Help centre" sections={DOCS_NAV} top={(folded) => <Brand folded={folded} name="Fernhill help" />} initialActive="set-up" initialExpanded={["start", "bookings"]}>
              {(active, label) => <DocsPage id={active} title={label} />}
            </Shell>
          </TabsContent>
        </div>
      </Tabs>
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

import { cn } from "@/lib/utils";

import { seededRandom } from "../../lib/plot";
import { type Status, STATUS_SURFACE, STATUS_TEXT } from "../../lib/status";

/** Props for the sample page inside the app layouts. */
export interface AppPageProps {
  /** The open place, which names the page and picks its sample figures. */
  id: string;
  title: string;
  /** The clinic the page belongs to, when the layout has one. */
  clinic?: string;
}

const PATIENTS = ["Amara Okafor", "Tomasz Nowak", "Hana Sato", "Diego Alvarez", "Freya Lindqvist", "Kwame Mensah", "Isla Mackenzie"];
const VISITS = ["Physiotherapy", "Blood test", "Dental check", "Hearing test", "Knee review", "Skin check", "Vaccination"];
const STATES: { word: string; tone: Status }[] = [
  { word: "Checked in", tone: "good" },
  { word: "Booked", tone: "watch" },
  { word: "Running late", tone: "bad" },
];

/** A whole number from a page id, so each page keeps the same sample data on every render. */
const seedOf = (text: string) => [...text].reduce((total, char) => total * 31 + char.charCodeAt(0), 7);

/**
 * A plain page for whichever place is open: a title, three figures and the
 * next visits with their state. The figures change with the place, so moving
 * through the sidebar visibly changes the page.
 */
export function AppPage({ id, title, clinic }: AppPageProps) {
  const random = seededRandom(seedOf(`${id}${clinic ?? ""}`));
  const figures = [
    { label: "Visits today", value: String(18 + Math.floor(random() * 30)) },
    { label: "Free slots", value: String(2 + Math.floor(random() * 9)) },
    { label: "No-shows this week", value: String(Math.floor(random() * 6)) },
  ];
  const rows = Array.from({ length: 5 }, (_, index) => ({
    time: `${String(9 + index).padStart(2, "0")}:${random() > 0.5 ? "30" : "00"}`,
    patient: PATIENTS[Math.floor(random() * PATIENTS.length)] ?? "",
    visit: VISITS[Math.floor(random() * VISITS.length)] ?? "",
    state: STATES[index === 0 ? 0 : Math.floor(random() * STATES.length)] ?? STATES[1]!,
  }));

  return (
    <div className="flex flex-col gap-5 p-5">
      <div>
        <h3 className="text-xl font-semibold tracking-tight">{title}</h3>
        <p className="text-sm text-muted-foreground">{clinic ? `${clinic}, ` : ""}Thursday 12 November</p>
      </div>
      <dl className="grid grid-cols-3 gap-px overflow-hidden rounded-xl border border-border bg-border">
        {figures.map((figure) => (
          <div key={figure.label} className="flex min-w-0 flex-col gap-1 bg-card px-3 py-3 @md:px-4">
            <dt className="truncate text-xs text-muted-foreground">{figure.label}</dt>
            <dd className="text-2xl font-semibold tabular-nums">{figure.value}</dd>
          </div>
        ))}
      </dl>
      <section aria-label="Next visits" className="flex flex-col gap-2">
        <h4 className="text-sm font-medium">Next visits</h4>
        <ul className="flex flex-col gap-1 rounded-xl border border-border p-1">
          {rows.map((row) => (
            <li key={`${row.time}-${row.patient}`} className="flex items-center gap-3 px-2 py-2">
              <span className="w-11 shrink-0 text-xs text-muted-foreground tabular-nums">{row.time}</span>
              <span className="flex min-w-0 flex-1 flex-col">
                <span className="truncate text-sm font-medium">{row.patient}</span>
                <span className="truncate text-xs text-muted-foreground">{row.visit}</span>
              </span>
              <span className={cn("shrink-0 rounded-full px-2 py-0.5 text-xs font-medium", STATUS_SURFACE[row.state.tone], STATUS_TEXT[row.state.tone])}>
                {row.state.word}
              </span>
            </li>
          ))}
        </ul>
      </section>
    </div>
  );
}

/**
 * Plot maths shared by the blocks. Every path is drawn in a 0 to 100 box, and
 * the SVG stretches it with `preserveAspectRatio="none"`, so a chart needs no
 * resize observer. Strokes keep their width through `vector-effect`.
 */

/** A repeatable random source, so sample data is the same on the server and in the browser. */
export function seededRandom(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state * 1664525 + 1013904223) >>> 0;
    return state / 4294967296;
  };
}

// Monday to Sunday: a working week that tails off, then a quiet weekend.
const WEEKDAY_LIFT = [0.35, 0.5, 0.2, 0.1, -0.05, -0.75, -1];

/** Sample data that moves from `start` to `end` with a working-week rhythm and some noise. */
export function makeSeries(seed: number, length: number, start: number, end: number, noise: number): number[] {
  const random = seededRandom(seed);
  return Array.from({ length }, (_, index) => {
    const progress = length === 1 ? 1 : index / (length - 1);
    const trend = start + (end - start) * progress;
    const week = (WEEKDAY_LIFT[index % 7] ?? 0) * noise * 0.6;
    return Math.max(0, trend + week + (random() - 0.5) * noise * 0.7);
  });
}

/** The lowest and highest value across several series, padded so a line never touches the frame. */
export function paddedExtent(series: number[][], padding = 0.12): [number, number] {
  const values = series.flat();
  const low = Math.min(...values);
  const high = Math.max(...values);
  const span = high - low || 1;
  return [Math.max(0, low - span * padding), high + span * padding];
}

/** Where a value sits in the box, from 0 at the top to 100 at the bottom. */
export function toY(value: number, [low, high]: [number, number]): number {
  return 100 - ((value - low) / (high - low || 1)) * 100;
}

/** Where a point sits across the box, from 0 to 100. */
export function toX(index: number, length: number): number {
  return length <= 1 ? 50 : (index / (length - 1)) * 100;
}

/** The value at a fractional position along a series, read off the straight line between its neighbours. */
function valueAt(values: number[], position: number): number {
  const left = Math.floor(position);
  const right = Math.min(values.length - 1, left + 1);
  const from = values[left] ?? 0;
  const to = values[right] ?? from;
  return from + (to - from) * (position - left);
}

/**
 * A line through `values` with a fixed number of segments. Two paths with the
 * same segment count can morph into each other, whatever their point counts.
 */
export function linePath(values: number[], extent: [number, number], samples = 60): string {
  if (values.length === 0) return "";
  const parts: string[] = [];
  for (let step = 0; step <= samples; step += 1) {
    const position = (step / samples) * (values.length - 1);
    const x = (step / samples) * 100;
    const y = toY(valueAt(values, position), extent);
    parts.push(`${step === 0 ? "M" : "L"}${x.toFixed(2)} ${y.toFixed(2)}`);
  }
  return parts.join(" ");
}

/** The same line, closed down to the bottom edge, for a filled area. */
export function areaPath(values: number[], extent: [number, number], samples = 60): string {
  const line = linePath(values, extent, samples);
  return line ? `${line} L100 100 L0 100 Z` : "";
}

/** Round axis values between the low and high of the plot. */
export function axisTicks([low, high]: [number, number], count = 4): number[] {
  return Array.from({ length: count }, (_, index) => low + ((high - low) * index) / (count - 1));
}

/** The percent change from `before` to `after`, or 0 when there is nothing to compare against. */
export function percentChange(before: number, after: number): number {
  return before === 0 ? 0 : ((after - before) / before) * 100;
}

/** The sum of a series. */
export function sum(values: number[]): number {
  return values.reduce((total, value) => total + value, 0);
}

/** The mean of a series. */
export function mean(values: number[]): number {
  return values.length === 0 ? 0 : sum(values) / values.length;
}

/** The three states a figure or a row can be in. */
export type Status = "good" | "watch" | "bad";

/** The text colour for each state. Each one passes 4.5 to 1 on a card in both themes. */
export const STATUS_TEXT = {
  good: "text-marketing-green-ink",
  watch: "text-marketing-amber-ink",
  bad: "text-marketing-orange-ink",
} satisfies Record<Status, string>;

/** A tinted surface for each state, for a pill or a cell. Pair it with the matching text colour. */
export const STATUS_SURFACE = {
  good: "bg-marketing-green-surface",
  watch: "bg-marketing-amber-surface",
  bad: "bg-marketing-orange-surface",
} satisfies Record<Status, string>;

/** The word a screen reader and a label use for each state. Colour never carries a state alone. */
export const STATUS_WORD = {
  good: "Good",
  watch: "Watch",
  bad: "At risk",
} satisfies Record<Status, string>;

/** The brand mark at the top of the app and docs sidebars. */
export function Brand({ folded, name }: { folded: boolean; name: string }) {
  return (
    <span className="flex h-11 items-center gap-2.5 px-1.5">
      <span aria-hidden="true" className="flex size-7 shrink-0 items-center justify-center rounded-lg border-2 border-chart-2 bg-card text-xs font-semibold">
        F
      </span>
      {folded ? <span className="sr-only">{name}</span> : <span className="truncate text-sm font-semibold">{name}</span>}
    </span>
  );
}

