"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import { type ReactNode, useEffect, useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { XIcon } from "../../parts/icons";
import { MenuIcon, SidebarIcon } from "../icons";
import { labelsOf, type NavSection, PEOPLE } from "./data";
import { NavTree } from "./nav-tree";

/** Props for an app shell with a sidebar. */
export interface ShellProps {
  /** The first step of the breadcrumb, such as the product or the clinic. */
  root: string;
  sections: NavSection[];
  /** What sits at the top of the sidebar: a logo or a switcher. Gets whether the sidebar is folded. */
  top: (folded: boolean) => ReactNode;
  initialActive: string;
  initialExpanded?: string[];
  /** The page for the open place. */
  children: (active: string, label: string) => ReactNode;
}

// Critically damped: the sidebar folds quickly and lands without a bounce.
const FOLD: Transition = { type: "spring", stiffness: 420, damping: 41, mass: 1 };
const INSTANT: Transition = { duration: 0 };
// Below this width the sidebar leaves the page and opens as a sheet. It matches the `@2xl` container size.
const SHEET_BELOW_PX = 672;

/** Whether a key press happened where typing or a menu owns the keys. */
function inField(target: EventTarget | null): boolean {
  return target instanceof HTMLElement && target.closest("input, textarea, select, [contenteditable='true'], [role='menu'], [role='dialog']") !== null;
}

/**
 * An app frame: a sidebar beside a page with a breadcrumb bar. The sidebar
 * folds to an icon rail on a spring; on a narrow frame it slides in as a
 * sheet instead. The [ key folds or opens it when focus is not in a field,
 * a menu or a dialog, and Escape closes the sheet.
 */
export function Shell({ root, sections, top, initialActive, initialExpanded = [], children }: ShellProps) {
  const reduceMotion = useReducedMotion();
  const transition = reduceMotion ? INSTANT : FOLD;
  const fillId = useId();
  const sheetFillId = useId();
  const rootRef = useRef<HTMLDivElement | null>(null);
  const sheetRef = useRef<HTMLDivElement | null>(null);
  const menuRef = useRef<HTMLButtonElement | null>(null);
  const [folded, setFolded] = useState(false);
  const [sheetOpen, setSheetOpen] = useState(false);
  const [active, setActive] = useState(initialActive);
  const [expanded, setExpanded] = useState(() => new Set(initialExpanded));
  const labels = labelsOf(sections);
  const current = labels.get(active) ?? { label: active };

  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      const frame = rootRef.current;
      if (!frame || event.key !== "[" || event.metaKey || event.ctrlKey || inField(event.target)) return;
      const focus = document.activeElement;
      if (focus !== document.body && !frame.contains(focus)) return;
      event.preventDefault();
      if (frame.offsetWidth < SHEET_BELOW_PX) setSheetOpen((open) => !open);
      else setFolded((value) => !value);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  useEffect(() => {
    if (sheetOpen) sheetRef.current?.querySelector("button")?.focus();
  }, [sheetOpen]);

  const closeSheet = () => {
    setSheetOpen(false);
    menuRef.current?.focus();
  };

  const select = (id: string) => {
    setActive(id);
    if (sheetOpen) closeSheet();
  };

  const toggleGroup = (id: string) =>
    setExpanded((set) => {
      const next = new Set(set);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });

  const sidebarBody = (rail: boolean, id: string) => (
    <>
      <div className="px-2 pt-3 pb-2">{top(rail)}</div>
      <nav aria-label={`${root} navigation`} className="scroll-fade-effect-y scrollbar-none min-h-0 flex-1 overflow-y-auto px-2 py-2">
        <NavTree sections={sections} active={active} onSelect={select} folded={rail} expanded={expanded} onToggleGroup={toggleGroup} fillId={id} />
      </nav>
    </>
  );

  return (
    <div ref={rootRef} className="relative flex h-136 overflow-hidden rounded-xl border border-border">
      <motion.aside
        initial={false}
        animate={{ width: folded ? "3.75rem" : "15rem" }}
        transition={transition}
        className="hidden shrink-0 flex-col overflow-hidden border-r border-border @2xl:flex"
      >
        {sidebarBody(folded, fillId)}
      </motion.aside>

      <div className="flex min-w-0 flex-1 flex-col">
        <div className="flex h-12 shrink-0 items-center gap-2 border-b border-border px-3">
          <Button ref={menuRef} type="button" variant="ghost" size="icon" aria-label="Open navigation" aria-expanded={sheetOpen} onClick={() => setSheetOpen(true)} className="size-8 @2xl:hidden">
            <MenuIcon aria-hidden="true" />
          </Button>
          <Button
            type="button"
            variant="ghost"
            size="icon"
            aria-label={folded ? "Unfold sidebar" : "Fold sidebar"}
            aria-keyshortcuts="["
            title={`${folded ? "Unfold" : "Fold"} sidebar ([)`}
            onClick={() => setFolded((value) => !value)}
            className="hidden size-8 @2xl:inline-flex"
          >
            <SidebarIcon aria-hidden="true" />
          </Button>
          <nav aria-label="Breadcrumb" className="min-w-0 flex-1">
            <ol className="flex min-w-0 items-center gap-1.5 text-sm">
              <li className="hidden truncate text-muted-foreground @md:block">{root}</li>
              {current.parent ? <li aria-hidden="true" className="hidden text-muted-foreground @md:block">/</li> : null}
              {current.parent ? <li className="hidden truncate text-muted-foreground @md:block">{current.parent}</li> : null}
              <li aria-hidden="true" className="hidden text-muted-foreground @md:block">/</li>
              <li className="relative min-w-0 overflow-hidden" aria-current="page">
                <AnimatePresence mode="popLayout" initial={false}>
                  <motion.span
                    key={current.label}
                    initial={reduceMotion ? { opacity: 0 } : { opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={reduceMotion ? { opacity: 0 } : { opacity: 0, y: -10 }}
                    transition={{ duration: 0.2, ease: [0.165, 0.84, 0.44, 1] }}
                    className="block truncate font-medium"
                  >
                    {current.label}
                  </motion.span>
                </AnimatePresence>
              </li>
            </ol>
          </nav>
          <ul aria-label="Online now" className="flex shrink-0 -space-x-1.5">
            {PEOPLE.map((person) => (
              <li key={person.initials} title={person.name} className={cn("flex size-7 items-center justify-center rounded-full bg-card text-xs font-semibold ring-2", person.ring)}>
                <span aria-hidden="true">{person.initials}</span>
                <span className="sr-only">{person.name}</span>
              </li>
            ))}
          </ul>
        </div>
        <main className="min-h-0 flex-1 overflow-y-auto">{children(active, current.label)}</main>
      </div>

      <AnimatePresence>
        {sheetOpen ? (
          <motion.div
            key="scrim"
            aria-hidden="true"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={closeSheet}
            className="absolute inset-0 z-20 bg-background/70 @2xl:hidden"
          />
        ) : null}
        {sheetOpen ? (
          <motion.div
            key="sheet"
            ref={sheetRef}
            role="dialog"
            aria-modal="true"
            aria-label={`${root} navigation`}
            initial={reduceMotion ? { opacity: 0 } : { x: "-100%" }}
            animate={reduceMotion ? { opacity: 1 } : { x: 0 }}
            exit={reduceMotion ? { opacity: 0 } : { x: "-100%" }}
            transition={transition}
            onKeyDown={(event) => {
              if (event.key === "Escape") {
                event.preventDefault();
                closeSheet();
              }
            }}
            className="absolute inset-y-0 left-0 z-30 flex w-64 max-w-4/5 flex-col border-r border-border bg-popover text-popover-foreground shadow-lg backdrop-blur-md @2xl:hidden"
          >
            <div className="flex h-12 shrink-0 items-center justify-between border-b border-border pr-2 pl-4">
              <span className="text-sm font-medium">{root}</span>
              <Button type="button" variant="ghost" size="icon" aria-label="Close navigation" onClick={closeSheet} className="size-8">
                <XIcon aria-hidden="true" />
              </Button>
            </div>
            {sidebarBody(false, sheetFillId)}
          </motion.div>
        ) : null}
      </AnimatePresence>
    </div>
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { ChevronRightIcon } from "../../parts/icons";
import type { NavSection } from "./data";

/** Props for the navigation tree. */
export interface NavTreeProps {
  sections: NavSection[];
  active: string;
  onSelect: (id: string) => void;
  /** Shows icons only, with each label kept for screen readers. */
  folded: boolean;
  expanded: Set<string>;
  onToggleGroup: (id: string) => void;
  /** Shared by the fill that glides to the active item. Unique per tree. */
  fillId: string;
}

// Critically damped: the fill and the groups settle with no wobble.
const GLIDE: Transition = { type: "spring", stiffness: 520, damping: 46, mass: 1 };
const INSTANT: Transition = { duration: 0 };

// One row of the tree: a link to a page, or the trigger of a group. The hover tint sits under the content.
const ITEM =
  "relative isolate flex h-9 w-full cursor-pointer items-center gap-2 rounded-lg px-3 text-sm font-medium outline-none hover:bg-accent hover:text-accent-foreground focus-visible:ring-2 focus-visible:ring-ring motion-safe:transition-colors";

/**
 * The sidebar's list of places. A group opens in place by height. Folded,
 * the tree shows icons only; a group then opens its first page.
 */
export function NavTree({ sections, active, onSelect, folded, expanded, onToggleGroup, fillId }: NavTreeProps) {
  const reduceMotion = useReducedMotion();
  const transition = reduceMotion ? INSTANT : GLIDE;

  const fill = (on: boolean) =>
    on ? <motion.span layoutId={fillId} transition={transition} aria-hidden="true" className="absolute inset-0 -z-10 rounded-lg bg-muted" /> : null;

  return (
    <div className="flex flex-col gap-4">
      {sections.map((section, sectionIndex) => (
        <div key={section.label ?? sectionIndex} className="flex flex-col gap-0.5">
          {section.label ? (
            <h3 className={cn("px-2.5 pb-1 text-xs font-medium text-muted-foreground", folded && "sr-only")}>{section.label}</h3>
          ) : null}
          <ul className="flex flex-col gap-0.5">
            {section.items.map((item) => {
              const Icon = item.icon;
              const children = item.children ?? [];
              const open = expanded.has(item.id) && !folded;
              const holdsActive = children.some((child) => child.id === active);
              const isActive = item.id === active || (folded && holdsActive);
              return (
                <li key={item.id}>
                  {children.length > 0 && !folded ? (
                    <Button
                      type="button"
                      variant={holdsActive ? "ghost" : "ghost"}
                      aria-expanded={open}
                      onClick={() => onToggleGroup(item.id)}
                      className="w-full justify-start"
                    >
                      <Icon aria-hidden="true" className="size-4 shrink-0" />
                      <span className="flex min-w-0 flex-1 items-center gap-2 font-medium">
                        <span className="min-w-0 flex-1 truncate text-left">{item.label}</span>
                        <ChevronRightIcon aria-hidden="true" className={cn("size-4 motion-safe:transition-transform", open && "rotate-90")} />
                      </span>
                    </Button>
                  ) : (
                    <a
                      href={`#${children[0]?.id ?? item.id}`}
                      aria-current={item.id === active ? "page" : undefined}
                      aria-label={folded ? (item.count === undefined ? item.label : `${item.label}, ${item.count} unread`) : undefined}
                      title={folded ? item.label : undefined}
                      onClick={(event) => {
                        event.preventDefault();
                        const first = children[0];
                        onSelect(!first ? item.id : holdsActive ? active : first.id);
                      }}
                      className={cn(ITEM, isActive ? "text-foreground" : "text-muted-foreground")}
                    >
                      {fill(isActive)}
                      <Icon aria-hidden="true" className="size-4 shrink-0" />
                      {folded ? null : <span className="min-w-0 flex-1 truncate text-left">{item.label}</span>}
                      {item.count !== undefined && !folded ? (
                        <span className="rounded-full bg-muted px-1.5 text-xs tabular-nums text-muted-foreground">{item.count}</span>
                      ) : null}
                      {item.count !== undefined && folded ? <span aria-hidden="true" className="absolute top-1.5 right-1.5 size-1.5 rounded-full bg-chart-1" /> : null}
                    </a>
                  )}
                  <AnimatePresence initial={false}>
                    {open ? (
                      <motion.ul
                        initial={reduceMotion ? { opacity: 0 } : { height: 0, opacity: 0 }}
                        animate={reduceMotion ? { opacity: 1 } : { height: "auto", opacity: 1 }}
                        exit={reduceMotion ? { opacity: 0 } : { height: 0, opacity: 0 }}
                        transition={reduceMotion ? INSTANT : { type: "spring", stiffness: 420, damping: 41, mass: 1 }}
                        className="ml-4.5 flex flex-col gap-0.5 overflow-hidden border-l border-border pl-2"
                      >
                        {children.map((child) => (
                          <li key={child.id}>
                            <a
                              href={`#${child.id}`}
                              aria-current={child.id === active ? "page" : undefined}
                              onClick={(event) => {
                                event.preventDefault();
                                onSelect(child.id);
                              }}
                              className={cn(ITEM, "h-8 font-normal", child.id === active ? "text-foreground" : "text-muted-foreground")}
                            >
                              {fill(child.id === active)}
                              <span className="truncate">{child.label}</span>
                            </a>
                          </li>
                        ))}
                      </motion.ul>
                    ) : null}
                  </AnimatePresence>
                </li>
              );
            })}
          </ul>
        </div>
      ))}
    </div>
  );
}

